WITH lines AS (SELECT id, customer_id, created_at, coupon_codes, key, value FROM carts LATERAL VIEW EXPLODE(attributes) x AS key, value) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, key, COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) FILTER (WHERE key = 'gift') AS gift_rows, GROUPING(DATE_TRUNC('HOUR', created_at)) AS gid FROM lines GROUP BY CUBE (DATE_TRUNC('HOUR', created_at), key) ORDER BY row_count ASC NULLS FIRST
